/// <summary>
/// Extends SysOperationServiceController
/// </summary>
class AVASetColorinReqTransController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// new method
/// </summary>
protected void new()
{
    super(classStr(AVASetColorinReqTransService), methodStr(AVASetColorinReqTransService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// default class description
/// </summary>
/// <returns>ClassDescription</returns>
public ClassDescription defaultCaption()
{
    return "@NDX:NXAHandDownColor";
}

/// <summary>
/// construct method
/// </summary>
/// <param name = "_executionMode">SysOperationExecutionMode, default SysOperationExecutionMode::Synchronous</param>
/// <returns>AVASetColoringReqTransController</returns>
public static AVASetColorinReqTransController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVASetColorinReqTransController controller;
    controller = new AVASetColorinReqTransController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

/// <summary>
/// main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    AVASetColorinReqTransController controller;
    AVASetColorinReqTransContract   contract;
    controller = AVASetColorinReqTransController::construct();
    contract = controller.getDataContractObject();
    controller.initQuery(contract);
    controller.parmShowDialog(true);
    //controller.parmArgs(_args);
    controller.startOperation();
}

/// <summary>
/// initQuery method
/// </summary>
/// <param name = "_dataContract">AVASetColoringReqTransContract</param>
/// <returns>Query</returns>
internal Query initQuery(AVASetColorinReqTransContract _dataContract)
{
    Query                query;
    QueryBuildDataSource queryBuildDataSource;
    QueryBuildRange      queryBuildRange;
    const str defColor = 'RAL 0000';

    query = new Query(queryStr(AVASetColorinReqTransQuery));

    queryBuildDataSource = sysQuery::findOrCreateDataSource(query,tableNum(inventdim));

    queryBuildRange = SysQuery::findOrCreateRange(queryBuildDataSource, fieldNum(InventDim, InventColorId));
    queryBuildRange.value(queryValue(defColor));
    //queryBuildRange.status(RangeStatus::Locked);  

    _dataContract.parmQuery(SysOperationHelper::base64Encode(query.pack()));

    return query;
}
